import{_ as o,c as t,o as e,a4 as r}from"./chunks/framework.BYxathSa.js";const T=JSON.parse('{"title":"Q1：从输入 URL 到页面展示发生了什么？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q1.md","filePath":"frontend/q1.md","lastUpdated":null}'),n={name:"frontend/q1.md"},l=r('<h1 id="q1-从输入-url-到页面展示发生了什么" tabindex="-1">Q1：从输入 URL 到页面展示发生了什么？ <a class="header-anchor" href="#q1-从输入-url-到页面展示发生了什么" aria-label="Permalink to &quot;Q1：从输入 URL 到页面展示发生了什么？&quot;">​</a></h1><p>这是一个经典的综合性问题，体现了你对网络、浏览器原理的整体理解。</p><ol><li><p><strong>URL 解析</strong><br> 浏览器判断输入的是搜索内容还是请求的 URL。如果是 URL，会补全协议（默认 http/https），解析出协议、域名、端口、路径、参数等。</p></li><li><p><strong>DNS 解析</strong><br> 域名需要被解析为 IP 地址。浏览器会依次查询：浏览器缓存 → 操作系统 hosts 文件 → 路由器缓存 → ISP 的 DNS 缓存。如果都未命中，则进行递归查询或迭代查询，最终从根域名服务器、顶级域名服务器到权威域名服务器，拿到对应的 IP 地址。</p></li><li><p><strong>建立 TCP 连接</strong><br> 浏览器与服务器进行三次握手以建立可靠连接：</p><ul><li>客户端发送 <code>SYN</code> 包，进入 <code>SYN_SENT</code> 状态。</li><li>服务器回复 <code>SYN+ACK</code> 包，进入 <code>SYN_RCVD</code> 状态。</li><li>客户端发送 <code>ACK</code> 包，双方进入 <code>ESTABLISHED</code> 状态。 如果是 HTTPS，还需进行 TLS 握手（协商协议版本、加密套件、交换证书、生成会话密钥），过程通常额外需要 2 个 RTT（往返时延）。</li></ul></li><li><p><strong>发送 HTTP 请求</strong><br> 浏览器构建 HTTP 请求报文（包含请求行、请求头、请求体），发送给服务器。</p></li><li><p><strong>服务器处理并响应</strong><br> 服务器收到请求后，由后端程序进行处理，可能会查询数据库或调用其他服务，最终返回包含状态码和响应头的 HTTP 响应报文。</p></li><li><p><strong>浏览器接收并解析渲染</strong><br> 这是最关键的一步，进入了浏览器的渲染流程：</p><ul><li><strong>解析 HTML，构建 DOM 树</strong>：浏览器将字节流解析为字符，再通过词法、语法分析生成 DOM 节点，最终形成树结构。</li><li><strong>解析 CSS，构建 CSSOM 树</strong>：解析 CSS 样式表，生成样式规则树。CSS 解析会阻塞渲染，因为页面需要知道最终的样式。</li><li><strong>合并生成 Render 树</strong>：将 DOM 树与 CSSOM 树结合，生成渲染树。这个过程会排除不可见的节点（如 <code>display: none</code>）。</li><li><strong>布局（回流/Reflow）</strong>：计算渲染树中每个节点的几何信息（在视口中的确切位置和大小）。</li><li><strong>绘制（重绘/Paint）</strong>：将各节点绘制成屏幕上的实际像素。</li><li><strong>合成（Composite）</strong>：如果页面中有分层，会把不同图层分开栅格化，最终由合成线程合并成页面，这个过程通常 GPU 参与，效率很高。</li></ul></li><li><p><strong>连接结束</strong><br> 数据传输完毕后，通过四次挥手断开 TCP 连接（若为 HTTP/1.1 <code>Connection: keep-alive</code> 则保持连接可复用）。</p></li></ol>',3),s=[l];function i(a,d,c,p,_,g){return e(),t("div",null,s)}const P=o(n,[["render",i]]);export{T as __pageData,P as default};
